        uk: 'Ти вже два тижні в подорожі. Сьогодні вранці ти був у старовинному замку, а ввечері зустрів інших туристів і вони запитали: «Як пройшов день?» Саме час розповісти англійською.',
        es: 'Ya llevas dos semanas de viaje. Esta mañana estuviste en un castillo antiguo y por la noche conociste a otros turistas que te preguntaron: «¿Cómo te fue el día?» Es el momento de contarlo en inglés.',
